package internal

import (
	"bytes"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// compatVersions are the releases whose files are in testdata/compat,
// generated by installing with that release. Add one per release.
var compatVersions = []string{"v0.3.0", "v0.4.0", "v0.5.0", "v0.6.0", "v0.7.0", "v0.8.0"}

// materializeCompat copies testdata/compat/<version> into a temp dir,
// replacing $ROOT with it, and returns an App for its config.
func materializeCompat(t *testing.T, version string) (*App, string) {
	t.Helper()
	root := t.TempDir()
	src := filepath.Join("testdata", "compat", version)
	err := filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		rel, _ := filepath.Rel(src, path)
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		info, err := d.Info()
		if err != nil {
			return err
		}
		mode := info.Mode().Perm()
		if d.Name() == "secrets.toml" {
			mode = 0o600 // git keeps only the executable bit
		}
		return writeFileAtomic(filepath.Join(root, rel), []byte(strings.ReplaceAll(string(data), "$ROOT", root)), mode)
	})
	if err != nil {
		t.Fatal(err)
	}
	app, _ := testAppAt(t, filepath.Join(root, "profiles", "config.toml"))
	app.Home = filepath.Join(root, "home")
	return app, root
}

// TestCompatFixtures loads what older releases wrote and checks that this
// version reads it and plans no change beyond recreating symlinks (not kept
// in the fixtures), rewriting outdated wrappers, tightening file modes and
// adding the profile marker.
func TestCompatFixtures(t *testing.T) {
	t.Parallel()
	for _, version := range compatVersions {
		t.Run(version, func(t *testing.T) {
			t.Parallel()
			app, root := materializeCompat(t, version)
			cfg, err := app.LoadConfig()
			if err != nil {
				t.Fatalf("load: %v", err)
			}
			work := cfg.Profiles["work"]
			if work == nil || work.Model != "sonnet" || work.Env["TEAM"] != "core" || work.Settings["effortLevel"] != "high" || cfg.Profiles["personal"] == nil {
				t.Fatalf("config not understood: %+v", cfg.Profiles)
			}
			if len(cfg.Undecoded) != 0 {
				t.Errorf("unknown keys: %v", cfg.Undecoded)
			}
			if d := CheckDivergence(cfg, app.BaseDir); len(d) != 0 {
				t.Errorf("files written by %s count as local edits: %+v", version, d)
			}
			plan, err := app.PlanInstall(cfg, InstallOptions{Sync: true})
			if err != nil {
				t.Fatalf("plan: %v", err)
			}
			for _, act := range plan {
				rel, _ := filepath.Rel(root, act.Path)
				switch {
				case act.Kind == "symlink":
				case act.Kind == "write" && strings.HasPrefix(rel, "bin/claude-"):
				case act.Kind == "write" && bytes.Equal(act.Before, act.Data):
					// Same content, tighter mode: 0.3 wrote profile files as 0644.
				case act.Kind == "write" && act.Before == nil && strings.HasSuffix(rel, filepath.Join(".cpm", "profile")):
					// The profile marker is newer than 0.3.
				default:
					t.Errorf("unexpected %s %s:\n%s", act.Kind, rel, act.Data)
				}
			}
		})
	}
}
